function LoginPage({onLogin}:{onLogin:(email:string,password:string)=>boolean}){const [email,setEmail]=useState('sofia.owner@maisonatlas.com');const [password,setPassword]=useState('demo-owner');const [error,setError]=useState('');return <div className="auth-screen reference-login"><div className="auth-art"><span className="brand-mark large">M</span><span className="eyebrow">ALLNEEDS - TOURISM / PLATFORM</span><h1>One account.<br/><em>Every operation.</em></h1><p>Secure access to your restaurant, travel, transport, activities and accommodation businesses.</p><div className="auth-proof"><ShieldCheck size={17}/><span><strong>Protected by business-aware access control</strong><small>Session, membership and permissions are verified before every workspace loads.</small></span></div></div><form className="auth-card profile-login" onSubmit={e=>{e.preventDefault();if(!onLogin(email,password))setError('Email or password incorrect. Use demo-owner for this demo.')}}><span className="eyebrow">WELCOME TO YOUR WORKSPACE</span><h2>Choose your profile.</h2><p>Click any profile to enter instantly, or sign in with an email.</p><div className="quick-profiles">{demoAccounts.map(account=><button type="button" className="quick-profile" key={account.email} onClick={()=>{setEmail(account.email);setPassword('demo-owner');onLogin(account.email,'demo-owner')}}><span className="quick-avatar">{account.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><span><strong>{account.name}</strong><small>{account.role}{account.businessId&&` · ${businessTypeLabels[businesses.find(b=>b.id===account.businessId)?.type||'restaurant']}`}</small></span><ArrowRight size={15}/></button>)}</div><div className="login-divider"><span>or sign in with email</span></div><label>Email<input aria-label="Email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input aria-label="Password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<p className="login-error">{error}</p>}<button className="primary full" type="submit">Enter workspace <ArrowRight size={15}/></button><small className="auth-note">Demo environment · Password: demo-owner</small></form></div>}
function ArchivedBusinessSelector({active,onSelect,onAll}:{active:Business|null;onSelect:(b:Business)=>void;onAll:()=>void}){const [open,setOpen]=useState(false);const [query,setQuery]=useState('');const matches=businesses.filter(b=>`${b.name} ${businessTypeLabels[b.type]}`.toLowerCase().includes(query.toLowerCase()));return <div className="business-selector"><button className="business-trigger" onClick={()=>setOpen(!open)}><span className="business-logo" style={{background:active?.accent||'#d9eee6'}}>{active?businessTypeIcons[active.type]:'◈'}</span><span><strong>{active?.name||'All Businesses'}</strong><small>{active?businessTypeLabels[active.type]:'Global owner dashboard'}</small></span><ChevronDown size={16}/></button>{open&&<div className="business-menu"><div className="business-search"><Search size={14}/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search businesses..."/></div><button className={!active?'selected':''} onClick={()=>{onAll();setOpen(false)}}><span className="business-logo all">◈</span><span><strong>All Businesses</strong><small>Global owner dashboard</small></span>{!active&&<Check size={15}/>}</button>{matches.map(b=><button key={b.id} className={active?.id===b.id?'selected':''} onClick={()=>{onSelect(b);setOpen(false)}}><span className="business-logo" style={{background:b.accent}}>{businessTypeIcons[b.type]}</span><span><strong>{b.name}</strong><small>{businessTypeLabels[b.type]} · {b.location}</small></span>{active?.id===b.id&&<Check size={15}/>}</button>)}</div>}</div>}
function GlobalDashboard({onSelect}:{onSelect:(b:Business)=>void}){const metrics=[['Total revenue','€ 248,640','+18.4%'],['Total expenses','€ 119,220','-4.2%'],['Total profit','€ 129,420','+23.1%'],['Outstanding','€ 31,840','12 invoices']];return <div className="global-dashboard"><section className="global-hero"><div><span className="eyebrow">OWNER VIEW · ALL BUSINESSES</span><h2>The whole portfolio,<br/><em>in one clear view.</em></h2><p>Move from the signal to the business that needs your attention. Every figure is scoped and traceable.</p></div><div className="portfolio-orbit"><strong>05</strong><span>active businesses<br/>under management</span></div></section><div className="global-stats">{metrics.map(([label,value,sub])=><div className="global-stat" key={label}><small>{label}</small><strong>{value}</strong><span>{sub}</span></div>)}</div><div className="portfolio-head"><div><span className="eyebrow">YOUR PORTFOLIO</span><h3>Business performance</h3></div><span>08 October 2026</span></div><div className="portfolio-grid">{businesses.map(b=><button className="portfolio-card" key={b.id} onClick={()=>onSelect(b)}><div className="portfolio-top"><span className="business-logo" style={{background:b.accent}}>{businessTypeIcons[b.type]}</span><ArrowRight size={15}/></div><h3>{b.name}</h3><small>{businessTypeLabels[b.type]} · {b.location}</small><div className="portfolio-values"><span><b>{b.type==='restaurant'?'€ 48,240':b.type==='travel-agency'?'€ 86,420':b.type==='transport'?'€ 37,850':b.type==='activities'?'€ 29,410':'€ 46,720'}</b><small>revenue</small></span><span><b>{b.type==='accommodation'?'78%':b.type==='transport'?'142':'24'}</b><small>{b.type==='accommodation'?'occupancy':b.type==='transport'?'trips':'operations'}</small></span></div><div className="portfolio-progress"><i style={{width:`${55+(b.id.length*3)%35}%`}}/></div></button>)}</div></div>}
const businessNav:Record<Exclude<BusinessType,'restaurant'>,string[]>= {'travel-agency':['Today','Client requests','Dossiers','Quotes','Reservations','Trips / Circuits','Services','Suppliers','Planning','Clients','Payments','Documents','Team','Reports','Settings'],transport:['Today','Transfers / trips','Reservations','Dispatch planning','Vehicles','Drivers','Clients','Payments','Maintenance','Incidents','Reports','Settings'],activities:['Today','Activities','Sessions / slots','Reservations','Participants','Planning','Guides','Equipment','Payments','Incidents','Reports','Settings'],accommodation:['Today','Reservations','Planning','Rooms / units','Guests','Check-in / Check-out','Housekeeping','Services','Payments','Team','Documents','Reports','Settings']};
const businessNavBase=Object.fromEntries(Object.entries(businessNav).map(([type,items])=>[type,[...items]])) as typeof businessNav;
const navPermissionKey=(item:string)=>item.toLowerCase().replaceAll(' & ','_').replaceAll(' ','_').replaceAll('-','_');
setInterval(()=>{try{const account=JSON.parse(sessionStorage.getItem('allneeds.account')||'null');if(!account||!account.businessId)return;const permissions:string[]=account.permissions||permissionsFor(account.role||'');for(const type of Object.keys(businessNav) as Exclude<BusinessType,'restaurant'>[]){businessNav[type]=businessNavBase[type].filter(item=>item==='Today'||permissions.includes('*')||permissions.includes(`${navPermissionKey(item)}.view`)||permissions.includes(`${item==='Client requests'?'client_requests':item==='Trips / Circuits'?'trips':item==='Transfers / trips'?'transfers':item==='Dispatch planning'?'dispatch':item==='Sessions / slots'?'sessions':item==='Rooms / units'?'rooms':item==='Check-in / Check-out'?'checkin':navPermissionKey(item)}.view`));}}catch{}},100);
function BusinessWorkspaceLegacy({business,onChange}:{business:Business;onChange:(b:Business)=>void}){const [page,setPage]=useState('Today');const nav=businessNav[business.type as Exclude<BusinessType,'restaurant'>]||[];const copy:Record<Exclude<BusinessType,'restaurant'>,{eyebrow:string;title:string;description:string;cards:string[]}>= { 'travel-agency':{eyebrow:'TRAVEL CONTROL TOWER',title:'Every journey, under control.',description:'Requests, dossiers, departures and margin in one agency workspace.',cards:['New client requests','Open dossiers','Quotes awaiting response','Upcoming departures']},transport:{eyebrow:'DISPATCH CONTROL TOWER',title:'Keep every journey moving.',description:'Drivers, vehicles and transfers coordinated from one dispatch room.',cards:["Today's trips",'Drivers working today','Available vehicles','Maintenance alerts']},activities:{eyebrow:'ACTIVITY CONTROL TOWER',title:'Make every session count.',description:'Bookings, participants, guides and equipment aligned for the day.',cards:["Today's sessions",'Available places','Active guides','Open incidents']},accommodation:{eyebrow:'PROPERTY CONTROL TOWER',title:'A better stay starts here.',description:'Arrivals, departures, occupancy and housekeeping in one calm workspace.',cards:["Today's arrivals","Today's departures",'Occupancy','Rooms to clean']}};const text=copy[business.type as Exclude<BusinessType,'restaurant'>];return <div className="business-workspace"><aside className="business-mini-nav"><span className="eyebrow">{businessTypeLabels[business.type].toUpperCase()}</span><nav>{nav.map((item,i)=><button key={item} className={page===item?'active':''} onClick={()=>setPage(item)}><span>{i===0?'◈':'·'}</span>{item}</button>)}</nav></aside><section className="business-main"><div className="business-context"><div><span className="eyebrow">{text.eyebrow}</span><h2>{page==='Today'?text.title:page}</h2><p>{page==='Today'?text.description:`Manage ${page.toLowerCase()} with business-scoped records and permissions.`}</p></div><span className="scoped-pill"><ShieldCheck size={13}/> Business scoped</span></div>{page==='Today'?<><div className="business-cards">{text.cards.map((card,i)=><div className="business-card" key={card}><small>{card}</small><strong>{['12','24','€ 18,420','08'][i]}</strong><span>{i===0?'Needs attention':'Updated today'} <ArrowRight size={13}/></span></div>)}</div><div className="business-lower"><section className="panel"><div className="panel-head"><div><span className="eyebrow">TODAY'S OPERATIONS</span><h3>Operational pulse</h3></div><button className="text-btn">View report <ArrowRight size={13}/></button></div>{['Morning briefing · 09:00','Supplier confirmation · 11:30','Payment deadline · 15:00','Team handover · 18:30'].map(item=><div className="business-row" key={item}><span className="live-dot"/><strong>{item}</strong><small>Business record · {business.name}</small><Check size={14}/></div>)}</section><section className="panel alert-panel"><span className="eyebrow">ATTENTION REQUIRED</span><h3>3 items need your review.</h3><p>Open alerts are isolated to {business.name}. Nothing from another business is shown here.</p><button className="primary">Open alerts <ArrowRight size={14}/></button></section></div></>:<div className="module-empty"><span className="business-logo" style={{background:business.accent}}>{businessTypeIcons[business.type]}</span><h3>{page}</h3><p>This specialized module is ready for business-scoped records, role permissions and audit history.</p><button className="primary">Create first record <Plus size={14}/></button></div>}</section></div>}
function LegacyPlatform(){const [session,setSession]=useState(()=>sessionStorage.getItem('allneeds.authenticated')==='true');const [account,setAccount]=useState<DemoAccount|null>(()=>{try{return JSON.parse(sessionStorage.getItem('allneeds.account')||'null')}catch{return null}});const [activeId,setActiveId]=useState<string|null>(()=>sessionStorage.getItem('allneeds.business')||null);const active=businesses.find(b=>b.id===activeId)||null;const login=(email:string,password:string)=>{const found=demoAccounts.find(item=>item.email.toLowerCase()===email.trim().toLowerCase())||null;if(!found||password!=='demo-owner')return false;sessionStorage.setItem('allneeds.authenticated','true');sessionStorage.setItem('allneeds.account',JSON.stringify(found));setAccount(found);setSession(true);if(found.businessId){sessionStorage.setItem('allneeds.business',found.businessId);setActiveId(found.businessId);const business=businesses.find(b=>b.id===found.businessId);history.replaceState({},'',business?`/business/${business.type}/dashboard`:'/businesses')}else history.replaceState({},'','/businesses');return true};const logout=()=>{sessionStorage.removeItem('allneeds.authenticated');sessionStorage.removeItem('allneeds.business');sessionStorage.removeItem('allneeds.account');setSession(false);setAccount(null);setActiveId(null);history.replaceState({},'', '/login')};if(!session)return <LoginPage onLogin={login}/>;const select=(business:Business)=>{sessionStorage.setItem('allneeds.business',business.id);setActiveId(business.id);history.replaceState({},'',`/business/${business.type}/dashboard`)};const all=()=>{sessionStorage.removeItem('allneeds.business');setActiveId(null);history.replaceState({},'','/businesses')};return <div className="platform-shell"><header className="platform-header"><div className="platform-brand"><span className="brand-mark">M</span><span>ALLNEEDS - TOURISM<small>UNIFIED BUSINESS PLATFORM</small></span></div><ArchivedBusinessSelector active={active} onSelect={select} onAll={all}/><div className="platform-actions"><span className="platform-user"><span className="avatar">{account?.name.split(' ').map(x=>x[0]).join('').slice(0,2)||'SB'}</span><span><strong>{account?.name||'Sofia Benali'}</strong><small>{account?.role||'Super Admin / Owner'}</small></span></span><button className="logout-btn" onClick={logout}>Log out</button></div></header><main className="platform-content">{active?.type==='restaurant'?<RestaurantApp account={account||undefined}/>:active?<BusinessWorkspaceLegacy business={active} onChange={select}/>:<GlobalDashboard onSelect={select}/>}</main></div>}
function Platform(){const [session,setSession]=useState(()=>sessionStorage.getItem('allneeds.authenticated')==='true');const [account,setAccount]=useState<DemoAccount|null>(()=>{try{return JSON.parse(sessionStorage.getItem('allneeds.account')||'null')}catch{return null}});const [activeId,setActiveId]=useState<string|null>(()=>sessionStorage.getItem('allneeds.business')||null);const active=businesses.find(b=>b.id===activeId)||null;const login=(email:string,password:string)=>{const found=demoAccounts.find(item=>item.email.toLowerCase()===email.trim().toLowerCase())||null;if(!found||password!=='demo-owner')return false;const next={...found,permissions:found.permissions||permissionsFor(found.role)};sessionStorage.setItem('allneeds.authenticated','true');sessionStorage.setItem('allneeds.account',JSON.stringify(next));setAccount(next);setSession(true);if(next.businessId){sessionStorage.setItem('allneeds.business',next.businessId);setActiveId(next.businessId);const business=businesses.find(b=>b.id===next.businessId);history.replaceState({},'',business?`/business/${business.type}/dashboard`:'/businesses')}else history.replaceState({},'','/businesses');return true};const logout=()=>{sessionStorage.clear();setSession(false);setAccount(null);setActiveId(null);history.replaceState({},'','/login')};if(!session)return <LoginPage onLogin={login}/>;const select=(business:Business)=>{if(account?.businessId&&account.businessId!==business.id){return}sessionStorage.setItem('allneeds.business',business.id);setActiveId(business.id);history.replaceState({},'',`/business/${business.type}/dashboard`)};const all=()=>{if(account?.businessId)return;sessionStorage.removeItem('allneeds.business');setActiveId(null);history.replaceState({},'','/businesses')};return <div className="platform-shell"><header className="platform-header"><div className="platform-brand"><span className="brand-mark">M</span><span>ALLNEEDS - TOURISM<small>UNIFIED BUSINESS PLATFORM</small></span></div><ArchivedBusinessSelector active={active} onSelect={select} onAll={all}/><div className="platform-actions"><span className="platform-user"><span className="avatar">{account?.name.split(' ').map(x=>x[0]).join('').slice(0,2)||'SB'}</span><span><strong>{account?.name}</strong><small>{account?.role}</small></span></span><button className="logout-btn" onClick={logout}>Log out</button></div></header><main className="platform-content">{active?.type==='restaurant'?<RestaurantApp account={account||undefined}/>:active?<BusinessWorkspace business={active}/>:<GlobalDashboard onSelect={select}/>}</main></div>}
createRoot(document.getElementById('root')!).render(<Platform/>);
